INSERT INTO `page_contents` (`id`, `slug`, `title`, `subtitle`, `body`, `image_path`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'about', 'About Doktors Clinic', 'Modern outpatient scheduling and coordinated care.', 'Doktors Clinic connects patients with verified specialists through a structured booking workflow, transparent visit windows, and clear financial summaries for each appointment.\r\n\r\nOur platform supports clinic administrators with oversight of doctor onboarding, specialty catalogues, and operational reporting, while doctors manage recurring availability and appointment outcomes. Patients can discover providers by specialty, review available hourly slots, and complete reservations with a documented payment method.\r\n\r\nThis environment is designed for reliable day-to-day clinic operations: every booking reserves discrete hour-level slots to prevent double scheduling, and commission settings are snapshotted per visit for consistent historical reporting.', NULL, 1, '2026-04-04 05:42:45', '2026-04-05 05:22:48'),
(2, 'contact', 'Contact Us', 'Reception, billing, and medical records.', '**Reception desk:** +966 11 555 0140 (08:00–20:00, Saturday–Thursday)\r\n\r\n**Billing inquiries:** billing@doktors-clinic.demo\r\n\r\n**Medical records / referrals:** records@doktors-clinic.demo\r\n\r\n**Address:** King Fahd Road, Al Olaya, Riyadh — Building 12, Floor 3\r\n\r\nFor urgent emergencies, please use your national emergency number or visit the nearest hospital emergency department.', NULL, 1, '2026-04-04 05:42:45', '2026-04-05 05:22:48');

