INSERT INTO `specialties` (`id`, `name`, `description`, `image_path`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Cardiology', 'Prevention, diagnosis, and treatment of heart and vascular disease, including hypertension, coronary artery disease, arrhythmias, and heart failure follow-up.', 'specialties/1861510649115236.webp', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(2, 'Dermatology', 'Skin, hair, and nail disorders—acne, eczema, psoriasis, infections, and screening for suspicious lesions—with both medical and procedural care options.', 'specialties/1861511170098071.webp', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(3, 'Orthopedics', 'Bones, joints, ligaments, and muscles: fractures, sports injuries, arthritis management, and pre- and post-operative musculoskeletal rehabilitation planning.', 'specialties/1861511223131855.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(4, 'Pediatrics', 'Healthcare for infants, children, and adolescents: growth monitoring, vaccinations, acute illness visits, and coordination with schools and caregivers.', 'specialties/1861511273602480.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(5, 'Neurology', 'Diagnosis and treatment of disorders of the brain, spinal cord, and peripheral nerves, including headaches, seizures, and movement disorders.', 'specialties/1861511309794122.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(6, 'Otolaryngology (ENT)', 'Ear, nose, and throat care including hearing assessments, sinus conditions, and voice disorders.', 'specialties/1861511524244317.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(7, 'Endocrinology', 'Management of hormone-related conditions such as diabetes, thyroid disorders, and metabolic syndrome.', 'specialties/1861511561093747.jpeg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(8, 'General Internal Medicine', 'Comprehensive adult primary care, preventive screenings, and coordination of chronic disease management.', 'specialties/1861511594045550.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(9, 'Rheumatology', 'Care for autoimmune and musculoskeletal conditions including arthritis, lupus, and inflammatory joint disease.', 'specialties/1861511639824742.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20'),
(10, 'Psychiatry', 'Assessment and treatment of mental health conditions with emphasis on evidence-based therapy and medication management.', 'specialties/1861511668439185.jpg', 1, '2026-04-04 05:42:45', '2026-04-17 05:38:20');

